contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint beforeBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractEther = address(c).balance;

        c.Collect(collectAmount); if (__ESBMC_reverted()) return;

        uint afterBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractEther = address(c).balance;

        bool precondition = beforeBalance >= c.MinSum() && beforeBalance >= collectAmount;
        assert(!precondition || (afterBalance == beforeBalance - collectAmount && afterContractEther <= beforeContractEther));
    }

    receive() external payable {}
}

